{% macro load_power_tag_metadata() %}

    {% set target_table = 'power_tag_metadata' %}

    {% set query %}
        DROP TABLE IF EXISTS {{ target_table }};

        CREATE TABLE {{ target_table }} (
            ts TIMESTAMP,
            power_tag_id INT,
            panel STRING,
            breaker STRING,
            "description" STRING,
            "name" STRING,
            topic STRING,
            main_group STRING,
            sub_group STRING,
            TIME INDEX (ts),
            PRIMARY KEY (topic)
        );

    {% endset %}

    {% do log("Create power tag metadata table and insert data...", info=True) %}
    {% do run_query(query) %}
    {% do log("Success! Data has been loaded.", info=True) %}

{% endmacro %}